}finally{$db->rollBack();}$after=$counts();$passed=!in_array(false,$checks,true)&&$before===$after;echo json_encode(['passed'=>$passed,'checks'=>$checks,'before'=>$before,'after'=>$after,'rolled_back'=>$before===$after],JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT).PHP_EOL;exit($passed?0:1);
